import Vapor
import Crypto
import Fluent

enum CommentCryptoError: Error {
    case missingKey
    case invalidCiphertext
    case invalidPlaintextEncoding
    case sealingFailed
}

struct CommentController: RouteCollection {
    func boot(routes: RoutesBuilder) throws {
        let comments = routes.grouped("comments")
        comments.post(use: createComment)
        comments.get(use: listComments)
    }

    // AES-GCM encryption for storing comments.
    // Load a persistent key from configuration so data remains decryptable
    // across restarts and multiple instances.
    private func loadEncryptionKey() throws -> SymmetricKey {
        guard let base64Key = Environment.get("COMMENT_ENCRYPTION_KEY"),
              let keyData = Data(base64Encoded: base64Key),
              keyData.count == 32 else {
            throw CommentCryptoError.missingKey
        }
        return SymmetricKey(data: keyData)
    }

    struct CommentInput: Content {
        var author: String
        var body: String
        var format: String? // "plain" or "markdown"
    }

    struct CommentOutput: Content {
        var id: UUID?
        var author: String
        var body: String
        var renderedBody: String
    }

    func createComment(req: Request) async throws -> CommentOutput {
        let input = try req.content.decode(CommentInput.self)
        let encryptionKey = try loadEncryptionKey()

        // Sanitize author field - strip HTML
        let sanitizedAuthor = HTMLSanitizer.stripAllTags(input.author)

        // Sanitize body based on format
        let sanitizedBody: String
        let format = input.format ?? "plain"

        if format == "markdown" {
            sanitizedBody = HTMLSanitizer.allowSafeMarkdown(input.body)
        } else {
            sanitizedBody = HTMLSanitizer.escapeHTML(input.body)
        }

        // Encrypt before storage
        let encryptedAuthor = try encrypt(sanitizedAuthor, using: encryptionKey)
        let encryptedBody = try encrypt(sanitizedBody, using: encryptionKey)
        let encryptedFormat = try encrypt(format, using: encryptionKey)

        let comment = Comment()
        comment.encryptedAuthor = encryptedAuthor
        comment.encryptedBody = encryptedBody
        comment.encryptedFormat = encryptedFormat
        try await comment.save(on: req.db)

        let rendered = renderForDisplay(body: sanitizedBody, format: format)

        return CommentOutput(
            id: comment.id,
            author: sanitizedAuthor,
            body: sanitizedBody,
            renderedBody: rendered
        )
    }

    func listComments(req: Request) async throws -> View {
        let comments = try await Comment.query(on: req.db).all()
        let encryptionKey = try loadEncryptionKey()

        var outputs: [CommentOutput] = []
        for comment in comments {
            let author = try decrypt(comment.encryptedAuthor, using: encryptionKey)
            let body = try decrypt(comment.encryptedBody, using: encryptionKey)
            let format = try decrypt(comment.encryptedFormat, using: encryptionKey)

            // Re-render from stored (already sanitized) content
            let rendered = renderForDisplay(body: body, format: format)

            outputs.append(CommentOutput(
                id: comment.id,
                author: author,
                body: body,
                renderedBody: rendered
            ))
        }

        return try await req.view.render("comments", ["comments": outputs])
    }

    private func renderForDisplay(body: String, format: String) -> String {
        if format == "markdown" {
            return MarkdownRenderer.toHTML(body)
        } else {
            // Plain text: wrap in paragraph tags
            return "<p>\(HTMLSanitizer.escapeHTML(body))</p>"
        }
    }

    private func encrypt(_ plaintext: String, using key: SymmetricKey) throws -> String {
        let data = Data(plaintext.utf8)
        let sealedBox = try AES.GCM.seal(data, using: key)
        guard let combined = sealedBox.combined else {
            throw CommentCryptoError.sealingFailed
        }
        return combined.base64EncodedString()
    }

    private func decrypt(_ ciphertext: String, using key: SymmetricKey) throws -> String {
        guard let data = Data(base64Encoded: ciphertext) else {
            throw CommentCryptoError.invalidCiphertext
        }
        let sealedBox = try AES.GCM.SealedBox(combined: data)
        let decrypted = try AES.GCM.open(sealedBox, using: key)
        guard let result = String(data: decrypted, encoding: .utf8) else {
            throw CommentCryptoError.invalidPlaintextEncoding
        }
        return result
    }
}

// MARK: - HTML Sanitizer
struct HTMLSanitizer {
    static func stripAllTags(_ input: String) -> String {
        return input.replacingOccurrences(
            of: "<[^>]+>",
            with: "",
            options: .regularExpression
        )
    }

    static func escapeHTML(_ input: String) -> String {
        return input
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&#x27;")
    }

    static func allowSafeMarkdown(_ input: String) -> String {
        // Escape all HTML first, then the markdown renderer handles formatting
        var result = escapeHTML(input)
        return result
    }
}

// MARK: - Markdown Renderer
struct MarkdownRenderer {
    static func toHTML(_ markdown: String) -> String {
        var html = markdown
        // Bold
        html = html.replacingOccurrences(
            of: "\\*\\*(.+?)\\*\\*",
            with: "<strong>$1</strong>",
            options: .regularExpression
        )
        // Italic
        html = html.replacingOccurrences(
            of: "\\*(.+?)\\*",
            with: "<em>$1</em>",
            options: .regularExpression
        )
        // Links: [text](url) - only allow http/https
        html = html.replacingOccurrences(
            of: "\\[(.+?)\\]\\((https?://[^\"\\)]+?)\\)",
            with: "<a href=\"$2\" rel=\"nofollow noopener\">$1</a>",
            options: .regularExpression
        )
        return html
    }
}

// MARK: - Model
final class Comment: Model {
    static let schema = "comments"

    @ID(key: .id) var id: UUID?
    @Field(key: "encrypted_author") var encryptedAuthor: String
    @Field(key: "encrypted_body") var encryptedBody: String
    @Field(key: "encrypted_format") var encryptedFormat: String

    init() {}
}
